import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

// Load fonts at module level to guarantee availability before frame 0
const { fontFamily: interFamily } = loadInter();
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type RotateDeviceProps = Record<string, any>;

const ArrowShape: React.FC<{ drawProgress: number }> = ({ drawProgress }) => {
  // Path length is mathematically ~576, using 600 ensures full coverage for dash offset
  const pathLength = 600;
  const dashOffset = pathLength * (1 - drawProgress);
  
  // Scale the arrowhead up rapidly just as the line finishes drawing
  const headScale = interpolate(drawProgress, [0.8, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <g>
      <path
        d="M -240 -120 A 280 280 0 0 1 240 -120"
        fill="none"
        stroke="currentColor"
        strokeWidth="24"
        strokeLinecap="round"
        strokeDasharray={pathLength}
        strokeDashoffset={dashOffset}
      />
      {/* Transform applies to the group to avoid SVG transform-origin inconsistencies across browsers */}
      <g transform={`translate(240, -120) rotate(59) scale(${headScale})`}>
        <polygon points="40,0 -30,-40 -30,40" fill="currentColor" />
      </g>
    </g>
  );
};

const RotateDevice: React.FC<RotateDeviceProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  iconColor = "#ffffff",
  durationInSeconds = 5,
  text = "Please rotate your device",
  textFontFamily = "Inter",
  loop = true,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Parser safety for transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const fontFamily = textFontFamily === "Inter" ? interFamily : spaceGroteskFamily;

  // Define a 3-second internal loop cycle for the continuous instructional motion
  const cycleLength = fps * 3;
  const localFrame = loop ? frame % cycleLength : Math.min(frame, cycleLength);

  // Animate the arrows drawing themselves in and out
  const drawProgress =
    localFrame < (cycleLength / 2)
      ? interpolate(localFrame, [5, 20], [0, 1], {
          easing: Easing.out(Easing.ease),
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        })
      : interpolate(localFrame, [cycleLength - 20, cycleLength - 5], [1, 0], {
          easing: Easing.inOut(Easing.ease),
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

  // Animate the phone rotating 90 degrees
  const phoneRotation =
    localFrame < (cycleLength / 2)
      ? interpolate(localFrame, [20, 40], [-90, 0], {
          easing: Easing.out(Easing.cubic),
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        })
      : interpolate(localFrame, [cycleLength - 20, cycleLength - 5], [0, -90], {
          easing: Easing.inOut(Easing.cubic),
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

  // Smooth global fade-in for the text
  const globalTextOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          position: "relative",
          width: 800,
          height: 800,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          color: iconColor,
        }}
      >
        {/* Arrows Container */}
        <div style={{ position: "absolute", width: "100%", height: "100%" }}>
          <svg
            width="100%"
            height="100%"
            viewBox="-400 -400 800 800"
            style={{ overflow: "visible" }}
          >
            {/* Top Right Curved Arrow */}
            <ArrowShape drawProgress={drawProgress} />
            {/* Bottom Left Curved Arrow (Identical shape, rotated 180 degrees) */}
            <g transform="rotate(180)">
              <ArrowShape drawProgress={drawProgress} />
            </g>
          </svg>
        </div>

        {/* Phone Outline */}
        <div
          style={{
            position: "absolute",
            width: 420,
            height: 200,
            borderRadius: 48,
            border: `24px solid currentColor`,
            transform: `rotate(${phoneRotation}deg)`,
            display: "flex",
            alignItems: "center",
            justifyContent: "flex-end",
            padding: 24,
            boxSizing: "border-box",
            transition: "none",
          }}
        >
          {/* Camera Dot Indicator */}
          <div
            style={{
              width: 20,
              height: 20,
              backgroundColor: "currentColor",
              borderRadius: "50%",
              transition: "none",
            }}
          />
        </div>
      </div>

      {/* Instructional Text */}
      {text && (
        <div
          style={{
            position: "absolute",
            bottom: 140,
            opacity: globalTextOpacity,
            color: iconColor,
            fontFamily,
            fontSize: 48,
            fontWeight: 600,
            letterSpacing: "-0.02em",
            textAlign: "center",
            width: "100%",
            transition: "none",
          }}
        >
          {text}
        </div>
      )}
    </AbsoluteFill>
  );
};

export default RotateDevice;